from langsmith import traceable, uuid7

@traceable
def my_pipeline(question: str) -> str:
    return "answer"

run_id = uuid7()
my_pipeline("What is the capital of France?", run_id=run_id)

@traceable(tags=["openai", "chat"], metadata={"foo": "bar"})
def invoke_runnable(question, context):
    result = chain.invoke({"question": question, "context": context})
    return "The response is: " + result

invoke_runnable("Summarize the meeting", "We solved all conflicts")

@traceable(name="Chat Bot", metadata={"thread_id": THREAD_ID})
def chat_pipeline(messages):
    return call_llm(messages)

@traceable(run_type="llm", name="Call LLM")
def call_llm(messages):
    return client.chat.completions.create(model=MODEL, messages=messages)

def process_inputs(inputs: dict) -> dict:
    key = inputs.get("my_cool_key", "default")
    return {"processed_key": key, "length": len(key)}

def process_outputs(output) -> dict:
    return {"processed_output": str(output)}

@traceable(process_inputs=process_inputs, process_outputs=process_outputs)
def my_function(my_cool_key: str) -> int:
    return len(my_cool_key)

my_function("example")

@traceable(
    run_type="llm",
    metadata={"ls_provider": "my_provider", "ls_model_name": "my_model"},
)
def chat_model(messages: list):
    run = get_current_run_tree()
    run.set(usage_metadata={"input_tokens": 27, "output_tokens": 13, "total_tokens": 40})
    return {"role": "assistant", "content": "Sure, what time?"}

from langsmith.run_helpers import get_current_run_tree, traceable

@traceable
async def my_client_function():
    headers = {}
    if run_tree := get_current_run_tree():
        headers.update(run_tree.______())
    return await client.post("/my-route", headers=headers)
